sp_widget.client_script:
function($scope,$rootScope) {
	var c = this;
	//set tile from options
	c.options.title = c.options.title || "${Refine Results}";
	c.clearAllEnable = false;
	c.items = [];
	c.articleCount = "";

	var refreshFilterIcon = $rootScope.$on('sp.kb.refresh.filter',function (event,data){
		if(data){
			c.items = data;
		}
		if(c.items.length>0){
			c.clearAllEnable = true;
		}else{
			c.clearAllEnable = false;
		}
	});
	c.clearAllFiters = function(){
		c.clearAllEnable = false;
		c.items = [];
		$rootScope.$emit('sp.kb.updated.filter','clearall');
		$('button.kb-fixed-facet-done').focus();
	};
var refreshResultCount = $rootScope.$on('sp.kb.refresh.sortorder',function (event,data){
	var count ="";
		if(data){
			count = data.article_count || '0';
			if(data.hasOwnProperty("article_count")){
					c.articleCount = count + " ${Results}";
			}
		}
});
	$scope.$on('$destroy',function(){
		refreshResultCount();
		refreshFilterIcon();
	});
}

sp_widget.css:
.panel{
  border-radius: 5px 5px 0 0;
  border: 1px solid #DDDDDD;
  margin-bottom:0px;
}
.panel-heading{
  padding: 10px 15px;
  margin-bottom:0px;
  height :40px;
  display:block;
  text-align: center;
}
.panel-title{
  color: #3A3F51;
  font-size:16px;
  padding-left:16px;
}
.loading-icon{
  text-align: center;
  padding: 10px;
}
.remove-bottom-border{
  border-bottom:0px;
}
.float-left{
  float:right;
}
.clear-all{
  float: left;
  font-size :15px;
}	
.articleCount{
  display:inline;
}
.width-82{
 width :82% !important;
  padding-left : 18%;
}
.doneCls{
  color: $text-color;
  float: right;
  font-size : 15px !important;
  text-align: right;
}
.facet-data{
  text-align: center;
  height: 40px;
  padding-top: 11px;
  color: #428bca;
}
.clear-enable{
  color: $text-color;
}	
.clear-disable {
  color : #979797;
}
.transparent-button{
  background-color: transparent;
  background-repeat:no-repeat;
  border: none;
  cursor:pointer;
  overflow: ellipsis;
  outline:none;
}
.fixed-facet-data-container{
  margin-bottom : 5px;
}

sp_widget.link:
function(scope) {	
	var c = scope.c;
	$rootScope = $injector.get("$rootScope");

	c.doneClick = function(){
		$rootScope.showFacet = false;
		if(!$rootScope.showLanguageFacet)
			setTimeout(function() { $('span.filter-icon').focus();},0);
		else
			setTimeout(function() { $('button.showLangIcon').focus();},0);
	}
}
